bool checkInclusion(string s1, string s2) {
    if (s1.size() > s2.size()) return false;
    vector<int> count1(26), count2(26);
    for (int i = 0; i < s1.size(); i++) {
        count1[s1[i]-'a']++;
        count2[s2[i]-'a']++;
    }
    int matches = 0;
    for (int i = 0; i < 26; i++) if (count1[i] == count2[i]) matches++;
    for (int i = s1.size(); i < s2.size(); i++) {
        if (matches == 26) return true;
        int r = s2[i] - 'a', l = s2[i - s1.size()] - 'a';
        count2[r]++;
        if (count2[r] == count1[r]) matches++; else if (count2[r] == count1[r] + 1) matches--;
        count2[l]--;
        if (count2[l] == count1[l]) matches++; else if (count2[l] == count1[l] - 1) matches--;
    }
    return matches == 26;
}
